 #define USART_CR1_TE (1U << 3)
 #define USART_ISR_TXE (1U << 7)

+/* --- I2C1: PB8 = SCL, PB9 = SDA (AF4, open-drain) --------------------- */
+#define GPIOB_BASE 0x48000400UL
+#define GPIOB_MODER (*(volatile uint32_t *)(GPIOB_BASE + 0x00))
+#define GPIOB_OTYPER (*(volatile uint32_t *)(GPIOB_BASE + 0x04))
+#define GPIOB_AFRH (*(volatile uint32_t *)(GPIOB_BASE + 0x24))
+
+#define RCC_AHBENR_IOPBEN (1U << 18)
+#define RCC_APB1ENR_I2C1EN (1U << 21)
+
+#define I2C1_BASE 0x40005400UL
+#define I2C1_CR1 (*(volatile uint32_t *)(I2C1_BASE + 0x00))
+#define I2C1_CR2 (*(volatile uint32_t *)(I2C1_BASE + 0x04))
+#define I2C1_TIMINGR (*(volatile uint32_t *)(I2C1_BASE + 0x10))
+#define I2C1_ISR (*(volatile uint32_t *)(I2C1_BASE + 0x18))
+#define I2C1_ICR (*(volatile uint32_t *)(I2C1_BASE + 0x1C))
+#define I2C1_RXDR (*(volatile uint32_t *)(I2C1_BASE + 0x24))
+#define I2C1_TXDR (*(volatile uint32_t *)(I2C1_BASE + 0x28))
+
+#define I2C_CR1_PE (1U << 0)
+#define I2C_CR2_RD_WRN (1U << 10)
+#define I2C_CR2_START (1U << 13)
+#define I2C_CR2_AUTOEND (1U << 25)
+#define I2C_ISR_TXIS (1U << 1)
+#define I2C_ISR_RXNE (1U << 2)
+#define I2C_ISR_TC (1U << 6)
+
+/* BME280 breakout, SDO tied low -> 7-bit address 0x76 (datasheet 5.4.1). */
+#define BME280_ADDR 0x76U
+#define BME280_CHIP_ID 0x60U
+#define BME280_REG_ID 0xD0U
+#define BME280_REG_CTRL_HUM 0xF2U
+#define BME280_REG_CTRL_MEAS 0xF4U
+#define BME280_REG_CONFIG 0xF5U
+#define BME280_REG_DATA 0xF7U
+#define BME280_REG_CALIB_T 0x88U
+#define BME280_REG_CALIB_H1 0xA1U
+#define BME280_REG_CALIB_H2 0xE1U
+
+#define I2C_SPIN_TIMEOUT 48000U
+
 /* --- startup (same shape as examples/firmware) ------------------------ */
 extern uint32_t _sidata, _sdata, _edata, _sbss, _ebss, _estack;

@@ -103,6 +143,129 @@
     uart2_write(&tmp[i + 1]);
 }

+/* Print a value in tenths as "<int>.<frac>", e.g. 243 -> "24.3". */
+static void uart2_write_dec1(int32_t tenths) {
+    if (tenths < 0) {
+        uart2_write("-");
+        tenths = -tenths;
+    }
+    uart2_write_uint((unsigned)(tenths / 10));
+    uart2_write(".");
+    uart2_write_uint((unsigned)(tenths % 10));
+}
+
+static void i2c1_init(void) {
+    RCC_AHBENR |= RCC_AHBENR_IOPBEN;
+    RCC_APB1ENR |= RCC_APB1ENR_I2C1EN;
+    /* PB8/PB9 -> AF4, open-drain; the 4.7k pull-ups sit on the breakout. */
+    GPIOB_MODER &= ~((3U << (8 * 2)) | (3U << (9 * 2)));
+    GPIOB_MODER |= (2U << (8 * 2)) | (2U << (9 * 2));
+    GPIOB_OTYPER |= (1U << 8) | (1U << 9);
+    GPIOB_AFRH |= (4U << 0) | (4U << 4);
+    /* 100 kHz standard mode from the 8 MHz HSI (RM0316 I2C timing example). */
+    I2C1_TIMINGR = 0x10420F13U;
+    I2C1_CR1 = I2C_CR1_PE;
+}
+
+static int i2c1_wait(uint32_t flag, const char *what) {
+    for (uint32_t spin = 0; spin < I2C_SPIN_TIMEOUT; spin++) {
+        if (I2C1_ISR & flag) {
+            return 0;
+        }
+    }
+    uart2_write("I2C1 ERROR: timeout waiting for ");
+    uart2_write(what);
+    uart2_write("\r\n");
+    return -1;
+}
+
+static int bme280_write_reg(uint8_t reg, uint8_t val) {
+    I2C1_CR2 = (uint32_t)BME280_ADDR | (2U << 16) | I2C_CR2_AUTOEND | I2C_CR2_START;
+    if (i2c1_wait(I2C_ISR_TXIS, "TXIS (write reg)") != 0) {
+        return -1;
+    }
+    I2C1_TXDR = reg;
+    if (i2c1_wait(I2C_ISR_TXIS, "TXIS (write val)") != 0) {
+        return -1;
+    }
+    I2C1_TXDR = val;
+    return 0;
+}
+
+static int bme280_read_regs(uint8_t reg, uint8_t *dst, uint32_t n) {
+    /* Pointer write without AUTOEND, then repeated-start read of n bytes. */
+    I2C1_CR2 = (uint32_t)BME280_ADDR | (1U << 16) | I2C_CR2_START;
+    if (i2c1_wait(I2C_ISR_TXIS, "TXIS (read setup)") != 0) {
+        return -1;
+    }
+    I2C1_TXDR = reg;
+    if (i2c1_wait(I2C_ISR_TC, "TC (read setup)") != 0) {
+        return -1;
+    }
+    I2C1_CR2 = (uint32_t)BME280_ADDR | I2C_CR2_RD_WRN | (n << 16) | I2C_CR2_AUTOEND |
+               I2C_CR2_START;
+    for (uint32_t i = 0; i < n; i++) {
+        if (i2c1_wait(I2C_ISR_RXNE, "RXNE (read data)") != 0) {
+            return -1;
+        }
+        dst[i] = (uint8_t)I2C1_RXDR;
+    }
+    return 0;
+}
+
+/* --- BME280 calibration + Bosch integer compensation ------------------ */
+static uint16_t dig_T1;
+static int16_t dig_T2, dig_T3;
+static uint8_t dig_H1, dig_H3;
+static int16_t dig_H2, dig_H4, dig_H5;
+static int8_t dig_H6;
+static int32_t t_fine;
+
+static int bme280_load_calib(void) {
+    uint8_t t[6], h1, h[7];
+    if (bme280_read_regs(BME280_REG_CALIB_T, t, 6) != 0 ||
+        bme280_read_regs(BME280_REG_CALIB_H1, &h1, 1) != 0 ||
+        bme280_read_regs(BME280_REG_CALIB_H2, h, 7) != 0) {
+        return -1;
+    }
+    dig_T1 = (uint16_t)(t[0] | (t[1] << 8));
+    dig_T2 = (int16_t)(t[2] | (t[3] << 8));
+    dig_T3 = (int16_t)(t[4] | (t[5] << 8));
+    dig_H1 = h1;
+    dig_H2 = (int16_t)(h[0] | (h[1] << 8));
+    dig_H3 = h[2];
+    dig_H4 = (int16_t)((h[3] << 4) | (h[4] & 0x0F));
+    dig_H5 = (int16_t)((h[5] << 4) | (h[4] >> 4));
+    dig_H6 = (int8_t)h[6];
+    return 0;
+}
+
+/* Bosch reference integer compensation (datasheet 4.2.3). Returns 0.01 degC. */
+static int32_t bme280_comp_temp(int32_t adc_T) {
+    int32_t var1 = (((adc_T >> 3) - ((int32_t)dig_T1 << 1)) * (int32_t)dig_T2) >> 11;
+    int32_t var2 = (((((adc_T >> 4) - (int32_t)dig_T1) *
+                      ((adc_T >> 4) - (int32_t)dig_T1)) >> 12) *
+                    (int32_t)dig_T3) >> 14;
+    t_fine = var1 + var2;
+    return (t_fine * 5 + 128) >> 8;
+}
+
+/* Bosch reference integer compensation (datasheet 4.2.3). Returns %RH Q22.10. */
+static uint32_t bme280_comp_hum(int32_t adc_H) {
+    int32_t v = t_fine - 76800;
+    v = ((((adc_H << 14) - ((int32_t)dig_H4 << 20) - ((int32_t)dig_H5 * v)) + 16384) >> 15) *
+        (((((((v * (int32_t)dig_H6) >> 10) * (((v * (int32_t)dig_H3) >> 11) + 32768)) >> 10) +
+           2097152) * (int32_t)dig_H2 + 8192) >> 14);
+    v = v - (((((v >> 15) * (v >> 15)) >> 7) * (int32_t)dig_H1) >> 4);
+    if (v < 0) {
+        v = 0;
+    }
+    if (v > 419430400) {
+        v = 419430400;
+    }
+    return (uint32_t)v >> 12;
+}
+
 int main(void) {
     uart2_init();
     GPIOA_MODER &= ~(3U << (LED_PIN * 2));
@@ -111,12 +274,64 @@
